import{_ as p,a0 as o,w as d,s as c,I as e,x as a,a1 as i,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"關於 Emacs 中的變量你需要知道的事情 | LCTT x X-CMD","titleTemplate":false,"description":"關於 Emacs 中的變量你需要知道的事情 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於 Emacs 中的變量你需要知道的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於 Emacs 中的變量你需要知道的事情 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200311 What you need to know about variables in Emacs","title":"關於 Emacs 中的變量你需要知道的事情","tag":"202004","desc":""},"relativePath":"202004/20200311 What you need to know about variables in Emacs.md","filePath":"[post].md"}'),r={name:"202004/20200311 What you need to know about variables in Emacs.md"};function u(h,s,g,m,b,k){const n=o("Link");return d(),c("div",null,[s[32]||(s[32]=e("h1",{id:"關於-emacs-中的變量你需要知道的事情",tabindex:"-1"},[a("關於 Emacs 中的變量你需要知道的事情 "),e("a",{class:"header-anchor",href:"#關於-emacs-中的變量你需要知道的事情","aria-label":"Permalink to “關於 Emacs 中的變量你需要知道的事情”"},"​")],-1)),s[33]||(s[33]=e("blockquote",null,[e("p",null,"學習 Elisp 是如何處理變量的，以及如何在你的腳本與配置中使用它們。")],-1)),s[34]||(s[34]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/25/190905pq1qfk1f8f9qs9v8.jpg",alt:""})],-1)),s[35]||(s[35]=e("p",null,"GNU Emacs 是由 C 和 Emacs Lisp（Elisp，Lisp 編程語言的一種方言）寫成，它是一個編輯器的同時，又碰巧是 Elisp 的沙盒。因此，理解 Elisp 中的一些基本編程概念會對你有一些幫助。",-1)),e("p",null,[s[3]||(s[3]=a("如果你是 ",-1)),i(n,{href:"https://www.gnu.org/software/emacs/"},{default:t(()=>[...s[0]||(s[0]=[a("Emacs",-1)])]),_:1}),s[4]||(s[4]=a(" 新手，請先閲讀 Sacha Chua 的《",-1)),i(n,{href:"http://sachachua.com/blog/p/27144"},{default:t(()=>[...s[1]||(s[1]=[a("給 Emacs 新手的資源",-1)])]),_:1}),s[5]||(s[5]=a("》精品帖。本篇文章假定你熟悉常見的 Emacs 術語，並且能夠閲讀並求值 Elisp 代碼的簡單片段。最好你也聽説過變量作用域的概念，知道它在其它編程語言中的作用。本篇文章中的示例假定你使用的是相對較新的 Emacs 版本（",-1)),i(n,{href:"https://www.gnu.org/software/emacs/download.html"},{default:t(()=>[...s[2]||(s[2]=[a("v.25 之後的版本",-1)])]),_:1}),s[6]||(s[6]=a("）。",-1))]),e("p",null,[i(n,{href:"https://www.gnu.org/software/emacs/manual/html_node/elisp/"},{default:t(()=>[...s[7]||(s[7]=[a("Elisp 手冊",-1)])]),_:1}),s[8]||(s[8]=a(" 包含了 Elisp 的方方面面，但它是寫給那些有明確查找目標的人們的（它在這方面也做得相當棒）。但是很多人想要能夠在更高的層次上解釋 Elisp 概念的材料，同時將信息壓縮成最精華的部分。本篇文章也正是我回應這種呼聲的一次嘗試，為讀者描繪基礎的大體輪廓。使他們能在配置中用上這些技巧，也讓他們在手冊中查詢細節變得更容易。",-1))]),s[36]||(s[36]=l(`<h3 id="全局變量" tabindex="-1">全局變量 <a class="header-anchor" href="#全局變量" aria-label="Permalink to “全局變量”">​</a></h3><p>用 <code>defcustom</code> 定義的用户設置和用 <code>defvar</code> 或 <code>defconst</code> 定義的變量是全局的。使用 <code>defcustom</code> 或 <code>defvar</code> 聲明變量的一個非常重要的原因是，當一個變量已經被<ruby>綁定<rt>bind</rt></ruby>，對它們進行重新求值不會覆蓋掉已有的值。舉個栗子，如果你在初始化文件中對 <code>my-var</code> 進行如下綁定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setq my-var nil)</span></span></code></pre></div><p>對如下表達式求值不會將變量覆蓋為 <code>t</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(defvar my-var t)</span></span></code></pre></div><p>注意此處有<em>一個例外</em>：如果你用 <code>C-M-x</code> 快捷鍵對上述聲明求值，它將調用 <code>eval-defun</code> 函數，並將變量覆蓋為 <code>t</code>。通過此方式，你可以按需將變量強制覆蓋。這種行為是刻意而為之的：你可能知道，Emacs 中的許多特性是按需加載的，也可以稱為自動加載。如果那些文件中的聲明將變量覆蓋為它們的默認值，那它也就覆蓋了你初始化文件中的設置。</p><h3 id="用户選項" tabindex="-1">用户選項 <a class="header-anchor" href="#用户選項" aria-label="Permalink to “用户選項”">​</a></h3><p>用户選項就是使用 <code>defcustom</code> 聲明的全局變量。與使用 <code>defvar</code> 聲明的變量不同，這些變量可以用 <code>M-x customize</code> 界面來配置。據我所知，大部分人因為覺得它開銷較大而不經常使用。一旦你知道如何在你的初始化文件中設置變量，也就沒有理由一定要去使用它了。許多用户沒有意識到的一個細節是，通過 <code>customize</code> 的方式設置用户選項能夠執行代碼，有的時間可用來運行一些附加的配置説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(defcustom my-option t</span></span>
<span class="line"><span>  &quot;My user option.&quot;</span></span>
<span class="line"><span>  :set (lambda (sym val)</span></span>
<span class="line"><span>         (set-default sym val)</span></span>
<span class="line"><span>         (message &quot;Set %s to %s&quot; sym val)))</span></span></code></pre></div><p>若你對這段代碼求值，並鍵入 <code>M-x customize-option RET my-option RET</code> 運行 <code>customize</code> 界面，lambda 匿名函數就會被調用，回顯區域就會顯示出該選項的符號名與值。</p><p>如果你在初始化文件中使用 <code>setq</code> 改變該選項的值，那麼匿名函數不會運行。要想在 Elisp 中正確設置一個選項，你需要使用函數 <code>customize-set-variable</code>。或者，人們在他們的配置文件中使用了各種版本的 <code>csetq</code> 宏來自動處理（如你所願，你可以通過 GitHub 的代碼搜索發現更復雜的變體）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(defmacro csetq (sym val)</span></span>
<span class="line"><span>  \`(funcall (or (get &#39;,sym &#39;custom-set) &#39;set-default) &#39;,sym ,val))</span></span></code></pre></div>`,12)),e("p",null,[s[10]||(s[10]=a("若你正在使用 ",-1)),i(n,{href:"https://github.com/jwiegley/use-package#customizing-variables"},{default:t(()=>[...s[9]||(s[9]=[a("use-package",-1)])]),_:1}),s[11]||(s[11]=a(" 宏，",-1)),s[12]||(s[12]=e("code",null,":custom",-1)),s[13]||(s[13]=a(" 關鍵字會替你處理好以上這些。",-1))]),s[37]||(s[37]=l(`<p>在你將以上代碼放入到你的初始化文件中之後，你便可以使用 <code>csetq</code> 宏在設置變量的同時運行任何現存的 <code>setter</code> 函數。要證明這點，你可以使用此宏來改變上面定義的選項，並觀察回顯區域的消息輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(csetq my-option nil)</span></span></code></pre></div><h3 id="動態綁定與詞法綁定" tabindex="-1">動態綁定與詞法綁定 <a class="header-anchor" href="#動態綁定與詞法綁定" aria-label="Permalink to “動態綁定與詞法綁定”">​</a></h3><p>當你在使用其它編程語言時，你可能不會意識到動態綁定與詞法綁定的區別。當今的大部分編程語言使用詞法綁定，並且在學習變量作用域與變量查找時也沒有必要去了解它們之間的區別。</p><p>如此看來，Emacs Lisp 比較特殊因為動態綁定是默認選項，詞法綁定需要顯式啓用。這裏有一些歷史遺留原因，但在實際使用中，你應該<em>時刻</em>啓用詞法綁定，因為它更快並且不容易出錯。要啓用詞法綁定，只需將如下的註釋行作為你的 Emacs Lisp 文件的第一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;;; -*- lexical-binding: t; -*-</span></span></code></pre></div><p>另一種方式，你可以調用 <code>add-file-local-variable-prop-line</code>，在你選擇將變量 <code>lexical-binding</code> 置為 <code>t</code> 後，會自動插入如上的註釋行。</p><p>在加載包含如上特殊格式行的文件時，Emacs 會相應地設置變量，這意味着該緩衝區中的代碼加載時啓用了詞法綁定。若要採用交互式的方式，你可以調用 <code>M-x eval-buffer</code> 命令，它會將詞法綁定考慮在內。</p><p>既然你已經知道了如何啓用詞法綁定，那麼瞭解這些術語的含義就很明智了。對於動態綁定，在程序執行期間建立的最後一個綁定將用於變量查找。你可以通過將以下代碼放入空緩衝區並執行 <code>M-x eval buffer</code>，以對此進行測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(defun a-exists-only-in-my-body (a)</span></span>
<span class="line"><span>  (other-function))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(defun other-function ()</span></span>
<span class="line"><span>  (message &quot;I see \`a&#39;, its value is %s&quot; a))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(a-exists-only-in-my-body t)</span></span></code></pre></div><p>你可能會很驚訝地發現，在 <code>other-function</code> 中查找變量 <code>a</code> 竟然成功了。</p><p>若你在頂部添加了特殊的詞法綁定註釋後，重新運行前面的示例，這段代碼將拋出 <code>variable is void</code> 錯誤，因為 <code>other-functioin</code> 無法識別變量 <code>a</code>。如果你使用的是其它編程語言，這才是你所期望的行為。</p><p>啓用詞法綁定後，作用域會由周圍的代碼所定義。這並不單單是性能原因，時間也已經表明了詞法綁定才是更受喜愛的。</p><h3 id="特殊變量與動態綁定" tabindex="-1">特殊變量與動態綁定 <a class="header-anchor" href="#特殊變量與動態綁定" aria-label="Permalink to “特殊變量與動態綁定”">​</a></h3><p>如你所知，<code>let</code> 用於臨時建立局部綁定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(let ((a &quot;I&#39;m a&quot;)</span></span>
<span class="line"><span>      (b &quot;I&#39;m b&quot;))</span></span>
<span class="line"><span>  (message &quot;Hello, %s. Hello %s&quot; a b))</span></span></code></pre></div><p>接下來有趣的是——使用 <code>defcustom</code>、<code>defvar</code> 以及 <code>defconst</code> 定義的變量被稱為<em>特殊變量</em>，不論詞法綁定是否啓用，它們都將使用動態綁定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;;; -*- lexical-binding: t; -*-</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(defun some-other-function ()</span></span>
<span class="line"><span>  (message &quot;I see \`c&#39;, its value is: %s&quot; c))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(defvar c t)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(let ((a &quot;I&#39;m lexically bound&quot;)</span></span>
<span class="line"><span>      (c &quot;I&#39;m special and therefore dynamically bound&quot;))</span></span>
<span class="line"><span>  (some-other-function)</span></span>
<span class="line"><span>  (message &quot;I see \`a&#39;, its values is: %s&quot; a))</span></span></code></pre></div><p>通過 <code>C-h e</code> 切換至 <code>Messages</code> 緩衝區，查看上述示例輸出的消息。</p><p>使用 <code>let</code> 或者函數參數綁定的局部變量會遵循由 <code>lexical-binding</code> 變量定義的查找規則，但使用 <code>defvar</code>、<code>defconst</code> 或 <code>defcustom</code> 定義的全局變量，能夠沿着調用棧在 <code>let</code> 表達式中被修改。</p><p>這種技巧允許方便地進行特殊定製，並且經常在 Emacs 中被使用。這並不奇怪，畢竟 Emacs Lisp 最開始只提供動態綁定作為唯一選擇。下面是一個常見的示例，説明如何向只讀緩衝區臨時寫入數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(let ((inhibit-read-only t))</span></span>
<span class="line"><span>  (insert ...))</span></span></code></pre></div><p>這是另一個常見的示例，如何進行大小寫敏感的搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(let ((case-fold-search nil))</span></span>
<span class="line"><span>  (some-function-which-uses-search ...))</span></span></code></pre></div><p>動態綁定允許你採用作者未曾預料的方式對函數進行修改。對於像 Emacs 這樣設計使用的程序來説，這是個強大的工具與特性。</p><p>有一點需要注意：你可能會意外地使用局部變量名，該變量在其他地方被聲明為特殊變量。防止這種衝突的一個技巧是避免在局部變量名中使用下劃線。在我當前的 Emacs 會話中，以下代碼只留下少數潛在衝突的候選：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(let ((vars ()))</span></span>
<span class="line"><span>  (mapatoms</span></span>
<span class="line"><span>   (lambda (cand)</span></span>
<span class="line"><span>     (when (and (boundp cand)</span></span>
<span class="line"><span>                (not (keywordp cand))</span></span>
<span class="line"><span>                (special-variable-p cand)</span></span>
<span class="line"><span>                (not (string-match &quot;-&quot;</span></span>
<span class="line"><span>                                   (symbol-name cand))))</span></span>
<span class="line"><span>       (push cand vars))))</span></span>
<span class="line"><span>  vars) ;; =&gt; (t obarray noninteractive debugger nil)</span></span></code></pre></div><h3 id="緩衝區局部變量" tabindex="-1">緩衝區局部變量 <a class="header-anchor" href="#緩衝區局部變量" aria-label="Permalink to “緩衝區局部變量”">​</a></h3><p>每個緩衝區都能夠擁有變量的一個局部綁定。這就意味着對於任何變量，都會首先在當前緩衝區中查找緩衝區局部變量取代默認值。局部變量是 Emacs 中一個非常重要的特性，比如它們被主模式用來建立緩衝區範圍內的行為與設置。</p><p>事實上你已經在本文中見過<em>緩衝區局部變量</em>——也就是將 <code>lexical-binding</code> 在緩衝區範圍內設置為 <code>t</code> 的特殊註釋行。在 Emacs 中，在特殊註釋行中定義的緩衝區局部變量也被稱為<em>文件局部變量</em>。</p><p>任何的全局變量都可以用緩衝區局部變量來遮掩，比如上面定義的變量 <code>my-var</code>，你可用如下方式設置局部變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setq-local my-var t)</span></span>
<span class="line"><span>;; or (set (make-local-variable &#39;my-var) t)</span></span></code></pre></div><p>此時 <code>my-var</code> 對於你在對上述代碼進行求值時對應的緩衝區來説就是局部變量。若你對它調用 <code>describe-variable</code>，文檔會同時告訴你局部與全局的值。從編程的角度來講，你可以分別用 <code>buffer-local-value</code> 獲取局部值，用 <code>default-value</code> 獲取全局值。若要移除局部值，你可以調用 <code>kill-local-variable</code>。</p><p>另一個需要注意的重要性質就是，一旦一個變量成為緩衝區局部變量，後續在該緩衝區中使用的 <code>setq</code> 都將只能設置局部的值。要想設置默認值，你需要使用 <code>setq-default</code>。</p><p>因為局部變量意味着對緩衝區的定製，它們也就經常被用於模式鈎子中。一個典型的例子如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(add-hook &#39;go-mode-hook</span></span>
<span class="line"><span>          (defun go-setup+ ()</span></span>
<span class="line"><span>            (setq-local compile-command</span></span>
<span class="line"><span>              (if (string-suffix-p &quot;_test.go&quot; buffer-file-name)</span></span>
<span class="line"><span>                  &quot;go test -v&quot;</span></span>
<span class="line"><span>                (format &quot;go run %s&quot;</span></span>
<span class="line"><span>                        (shell-quote-argument</span></span>
<span class="line"><span>                         (file-name-nondirectory buffer-file-name)))))))</span></span></code></pre></div><p>這將設置 <code>go-mode</code> 緩衝區中 <code>M-x compile</code> 使用的編譯命令。</p><p>另一個重要的方面就是一些變量會<em>自動</em>成為緩衝區局部變量。這也就意味着當你使用 <code>setq</code> 設置這樣一個變量時，它會針對當前緩衝區設置局部綁定。這個特性不應該被經常使用，因為這種隱式的行為並不好。不過如果你想的話，你可以使用如下方法創建自動局部變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(defvar-local my-automatical-local-var t)</span></span>
<span class="line"><span>;; or (make-variable-buffer-local &#39;my-automatical-local-var)</span></span></code></pre></div><p>變量 <code>indent-tabs-mode</code> 就是 Emacs 內建的一個例子。如果你在初始化文件中使用 <code>setq</code> 改變變量的值，根本不會影響默認值。只有在你加載初始化文件時正處在當前的緩衝區的局部值會被改變。因此，你需要使用 <code>setq-default</code> 來改變 <code>indent-tabs-mode</code> 的默認值。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>Emacs 是一個強大的編輯器，並且隨着你的定製它將變得更加強大。現在，你知道了 Elisp 是如何處理變量的，以及你應如何在你自己的腳本與配置中使用它們。</p>`,42)),e("p",null,[e("em",null,[s[15]||(s[15]=a("本篇文章此前採用 CC BY-NC-SA 4.0 許可證發佈在 ",-1)),i(n,{href:"https://with-emacs.com/posts/tutorials/almost-all-you-need-to-know-about-variables/"},{default:t(()=>[...s[14]||(s[14]=[a("With-Emacs",-1)])]),_:1}),s[16]||(s[16]=a(" 上，經過修改（帶有合併請求）並在作者允許的情況下重新發布。",-1))])]),s[38]||(s[38]=e("hr",null,null,-1)),e("p",null,[s[18]||(s[18]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/20/3/variables-emacs"},{default:t(()=>[...s[17]||(s[17]=[a("https://opensource.com/article/20/3/variables-emacs",-1)])]),_:1})]),e("p",null,[s[23]||(s[23]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/clemera"},{default:t(()=>[...s[19]||(s[19]=[a("Clemens Radermacher",-1)])]),_:1}),s[24]||(s[24]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[20]||(s[20]=[a("lujun9972",-1)])]),_:1}),s[25]||(s[25]=a(" 譯者：",-1)),i(n,{href:"https://github.com/cycoe"},{default:t(()=>[...s[21]||(s[21]=[a("cycoe",-1)])]),_:1}),s[26]||(s[26]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[22]||(s[22]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[27]||(s[27]=[a("LCTT",-1)])]),_:1}),s[30]||(s[30]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[28]||(s[28]=[a("Linux中國",-1)])]),_:1}),s[31]||(s[31]=a(" 榮譽推出",-1))])])}const C=p(r,[["render",u]]);export{v as __pageData,C as default};
